name: DCO Advisor Bot

on:
  pull_request_target:
    types: [opened, reopened, synchronize]

permissions:
  pull-requests: write
  issues: write

jobs:
  dco_advisor:
    runs-on: ubuntu-latest
    steps:
      - name: Handle DCO check result
        uses: actions/github-script@v7
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const pr = context.payload.pull_request || context.payload.check_run?.pull_requests?.[0];
            if (!pr) return;

            const prNumber = pr.number;
            const baseRef = pr.base.ref;
            const headSha =
              context.payload.check_run?.head_sha ||
              pr.head?.sha;
            const username = pr.user.login;

            console.log("HEAD SHA:", headSha);

            const sleep = ms => new Promise(resolve => setTimeout(resolve, ms));

            // Poll until DCO check has a conclusion (max 6 attempts, 30s)
            let dcoCheck = null;
            for (let attempt = 0; attempt < 6; attempt++) {
              const { data: checks } = await github.rest.checks.listForRef({
                owner: context.repo.owner,
                repo: context.repo.repo,
                ref: headSha
              });


              console.log("All check runs:");
                checks.check_runs.forEach(run => {
                console.log(`- ${run.name} (${run.status}/${run.conclusion}) @ ${run.head_sha}`);
              });

              dcoCheck = checks.check_runs.find(run =>
                run.name.toLowerCase().includes("dco") &&
              !run.name.toLowerCase().includes("dco_advisor") &&
                run.head_sha === headSha
              );


              if (dcoCheck?.conclusion) break;
              console.log(`Waiting for DCO check... (${attempt + 1})`);
              await sleep(5000); // wait 5 seconds
            }

            if (!dcoCheck || !dcoCheck.conclusion) {
              console.log("DCO check did not complete in time.");
              return;
            }

            const isFailure = ["failure", "action_required"].includes(dcoCheck.conclusion);
            console.log(`DCO check conclusion for ${headSha}: ${dcoCheck.conclusion} (treated as ${isFailure ? "failure" : "success"})`);

            // Parse DCO output for commit SHAs and author
            let badCommits = [];
            let authorName = "";
            let authorEmail = "";
            let moreInfo = `More info: [DCO check report](${dcoCheck?.html_url})`;

            if (isFailure) {
                const { data: commits } = await github.rest.pulls.listCommits({
                    owner: context.repo.owner,
                    repo: context.repo.repo,
                    pull_number: prNumber,
                });

                for (const commit of commits) {
                    const commitMessage = commit.commit.message;
                    const signoffMatch = commitMessage.match(/^Signed-off-by:\s+.+<.+>$/m);
                    if (!signoffMatch) {
                        console.log(`Bad commit found ${commit.sha}`)
                        badCommits.push({
                        sha: commit.sha,
                        authorName: commit.commit.author.name,
                        authorEmail: commit.commit.author.email,
                        });
                    }
                }            
            }

            // If multiple authors are present, you could adapt the message accordingly
            // For now, we'll just use the first one
            if (badCommits.length > 0) {
            authorName = badCommits[0].authorName;
            authorEmail = badCommits[0].authorEmail;
            }

            // Generate remediation commit message if needed
            let remediationSnippet = "";
            if (badCommits.length && authorEmail) {
              remediationSnippet = `git commit --allow-empty -s -m "DCO Remediation Commit for ${authorName} <${authorEmail}>\n\n` +
                badCommits.map(c => `I, ${c.authorName} <${c.authorEmail}>, hereby add my Signed-off-by to this commit: ${c.sha}`).join('\n') +
                `"`;
            } else {
              remediationSnippet = "# Unable to auto-generate remediation message. Please check the DCO check details.";
            }

            // Build comment
            const commentHeader = '<!-- dco-advice-bot -->';
            let body = "";

            if (isFailure) {
              body = [
                commentHeader,
                '❌ **DCO Check Failed**',
                '',
                `Hi @${username}, your pull request has failed the Developer Certificate of Origin (DCO) check.`,
                '',
                'This repository supports **remediation commits**, so you can fix this without rewriting history — but you must follow the required message format.',
                '',
                '---',
                '',
                '### 🛠 Quick Fix: Add a remediation commit',
                'Run this command:',
                '',
                '```bash',
                remediationSnippet,
                'git push',
                '```',
                '',
                '---',
                '',
                '<details>',
                '<summary>🔧 Advanced: Sign off each commit directly</summary>',
                '',
                '**For the latest commit:**',
                '```bash',
                'git commit --amend --signoff',
                'git push --force-with-lease',
                '```',
                '',
                '**For multiple commits:**',
                '```bash',
                `git rebase --signoff origin/${baseRef}`,
                'git push --force-with-lease',
                '```',
                '',
                '</details>',
                '',
                moreInfo
              ].join('\n');
            } else {
              body = [
                commentHeader,
                '✅ **DCO Check Passed**',
                '',
                `Thanks @${username}, all your commits are properly signed off. 🎉`
              ].join('\n');
            }

            // Get existing comments on the PR
            const { data: comments } = await github.rest.issues.listComments({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: prNumber
            });

            // Look for a previous bot comment
            const existingComment = comments.find(c =>
              c.body.includes("<!-- dco-advice-bot -->")
            );

            if (existingComment) {
              await github.rest.issues.updateComment({
                owner: context.repo.owner,
                repo: context.repo.repo,
                comment_id: existingComment.id,
                body: body
              });
            } else {
              await github.rest.issues.createComment({
                owner: context.repo.owner,
                repo: context.repo.repo,
                issue_number: prNumber,
                body: body
              });
            }

import logging
import time
from pathlib import Path
from typing import Iterator

import tqdm
from llama_index.core.llms.llm import LLM
from llama_index.core.prompts.utils import format_string
from pydantic import ConfigDict, ValidationError, validate_call

from docling_sdg.qa.base import (
    Critique,
    CritiqueOptions,
    CritiqueResult,
    GenQAC,
    Status,
)
from docling_sdg.qa.utils import (
    ChatAgent,
    initialize_llm,
    retrieve_stored_qac,
    retrieve_stored_qac_ids,
    save_to_file,
)

_log = logging.getLogger(__name__)


class Judge:
    def __init__(
        self,
        critique_options: CritiqueOptions,
    ):
        self.options = critique_options or CritiqueOptions()
        self.llm: LLM = initialize_llm(critique_options)
        self.agent = ChatAgent(llm=self.llm)

    @staticmethod
    def _get_eval_and_score(reply: str) -> Critique:
        required: list[str] = ["evaluation", "rating", "{", "}"]
        if not reply or any(item not in reply for item in required):
            critique: Critique = Critique(evaluation="non-valid", rating=None)
            _log.debug(f"Invalid critique reply: {reply}")
        else:
            dict_str = reply[reply.find("{") : reply.rfind("}") + 1]
            try:
                critique = Critique.model_validate_json(dict_str)
            except ValidationError as ve:
                _log.debug(f"Unable to instantiate a Critique from reply: {repr(ve)}")
                critique = Critique(evaluation="non-valid", rating=None)

        return critique

    def _critique_qac(self, qac: GenQAC) -> dict[str, Critique]:
        judge_result: dict[str, Critique] = {}

        for prompt_template in self.options.prompts:
            prompt = format_string(
                prompt_template.template,
                **{
                    x: getattr(qac, x.removesuffix("_str"))
                    for x in prompt_template.keys
                },
            )
            reply = self.agent.ask(prompt, self.options.max_new_tokens)
            judge_result[prompt_template.name] = Judge._get_eval_and_score(reply)

        return judge_result

    @validate_call(config=ConfigDict(strict=True))
    def critique(self, source: Path) -> CritiqueResult:
        _log.debug(f"Output file: {self.options.critiqued_file.absolute()}")
        start_time = time.time()

        qac_collection: Iterator[GenQAC] = retrieve_stored_qac(in_file=source)

        stored_critique_ids: list[str] = [
            qac_id for qac_id, _ in retrieve_stored_qac_ids(self.options.critiqued_file)
        ]
        num_stored_critiques: int = len(stored_critique_ids)

        num_exported_critiques: int = 0
        if num_stored_critiques >= self.options.max_qac:
            end_time = time.time()
        else:
            num_extra_critiques: int = self.options.max_qac - num_stored_critiques
            for qac in tqdm.tqdm(qac_collection):
                if num_exported_critiques >= num_extra_critiques:
                    break

                # If a QAC has already been critiqued, skip it
                if qac.qac_id in stored_critique_ids:
                    continue

                critique: dict[str, Critique] = self._critique_qac(qac)
                new_qac = qac.model_copy(update={"critiques": critique}, deep=True)

                num_exported_critiques += 1
                save_to_file(objects=[new_qac], out_file=self.options.critiqued_file)

            end_time = time.time()

        critique_res = CritiqueResult(
            status=Status.SUCCESS,
            time_taken=(end_time - start_time),
            num_qac=num_exported_critiques,
            output=self.options.critiqued_file,
        )

        return critique_res
